INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('arwic_mines_and_crafting', 1, 0, 'Leave town to the north and go east to the New Arwic Mines. Fight the Drudge Outcasts within to retrieve one of the miners'' flat hammers.' || char(10) || '' || char(10) || 'The Overseer told you, "Arwic''s rebuilding efforts have stalled! Supplies were cut off when the Drudge Outcasts overran my mines. The miners dropped their flat hammers during their escape. If you clear out the Drudges and return with a hammer, I will teach you the basics of crafting."', 'content/arwic-mines-v1.json phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('arwic_mines_and_crafting', 2, 0, 'Return to the Arwic Mines Overseer.', 'content/arwic-mines-v1.json phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('arwic_mines_and_crafting', 3, 0, 'Use the special quest recipe to craft an Arwic Mines Short Sword.' || char(10) || '' || char(10) || 'The Mines Overseer told you, "Click on the Craft Tab in your Skill panel. I have put a recipe for an Arwic Mines Short sword into your Quest recipes. Examine it to learn how to make the sword. When you succeed, give it to me so I can inspect your progress!"', 'content/arwic-mines-v1.json phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('arwic_mines_and_crafting', 4, 0, 'The Mines Overseer told you, "When you suceed in making the Arwic Mines Short Sword, give me the short sword so I can inspect your progress!"', 'content/arwic-mines-v1.json phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('arwic_mines_and_crafting', 5, 1, 'Lesson complete. You received 150 experience, an Arwic Outlands Glyph and The Shaper''s Guide. You may repeat this lesson after 20 hours.', 'Pyrealium text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('explore_arwic_obelisk_search', 1, 0, 'Press M to open your map panel to see where you are right now. Use your map panel and your compass to find the Arwic Ringway to North Outpost portal at 45.5 N, 7.5 W. After you''ve passed through, use the Ruby Obelisk on the other side. Time limit: 24 hours from acceptance.', 'exploration catalog phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('explore_arwic_obelisk_search', 2, 0, 'Press M to open your map panel to see where you are right now. Use your map panel and your compass to find the Arwic Ringway to East Outpost portal at 46.9 N, 0 E. After you''ve passed through, use the Sapphire Obelisk on the other side. Time limit: 24 hours from acceptance.', 'exploration catalog phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('explore_arwic_obelisk_search', 3, 0, 'Press M to open your map panel to see where you are right now. Use your map panel and your compass to find the Arwic Ringway to South Outpost portal at 42.1 N, 8.5 E. When you''ve passed through, use the Emerald Obelisk on the other side. Time limit: 24 hours from acceptance.', 'exploration catalog phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('explore_arwic_obelisk_search', 4, 0, 'The Arwic Explorer will be pleased to see your progress! Use the Arwic Ringway to Arwic Town portal at 34.3N, 2 W to return to him and receive your reward. Time limit: 24 hours from acceptance.', 'exploration catalog phases', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('explore_arwic_obelisk_search', 5, 1, 'Arwic Obelisk Search complete. Reward: 80 experience. Repeat after 20 hours.', 'exploration catalog', 'hand');
