INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 0, 0, 'Speak to the Shelter Guard to begin Rescue the Shelter Hold.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 1, 0, 'Rescue the Shelter Hold: read the training stones, then speak to the Shelter Lieutenant.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 2, 0, 'Rescue the Shelter Hold: continue through the training stones to the Shelter Sentry.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 3, 0, 'Defeat a Drudge Digger, collect its Imbued Digging Tool, then speak to the Shelter Scout. Leave room in your bag for three potions.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 4, 0, 'Defeat a Drudge Sentinel for its Menhir Glyph. Target the Menhir Portal and use the glyph from your backpack.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 5, 0, 'Speak to the Advance Shelter Scout in the Menhir Shard room.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 6, 1, 'Rescue the Shelter Hold complete. Walk down the passageway and use the Menhir Shard to enter Dereth.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 7, 1, 'Rescue the Shelter Hold complete. Seek out one of the Explorers.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_journey', 1, 0, 'A Safe Journey: use a lifestone to bind it, then use a training portal. Leave combat before both actions. Speak to a mentor at your destination for 80 experience and 10 gold. Rebind now even if you bound a lifestone before accepting this lesson.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_journey', 2, 0, 'A Safe Journey: your lifestone is bound. Leave combat and use a training portal, then speak to a training mentor at your destination.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_journey', 3, 0, 'A Safe Journey: you bound a lifestone and used a training portal. Speak to a training mentor for 80 experience and 10 gold.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_journey', 4, 1, 'Training complete! You finished combat, supplies, potion crafting and safe travel. You received the final 80 experience and 10 gold. The outdoor hub connects all three racial starts; its mentors and quartermasters remain available.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_potion', 1, 0, 'Potion Practice: buy a Mucor Mushroom and a 100-unit Tallow bundle, then use the crafting panel to create a health or vigor potion. Bought potions do not count. Return to a mentor after crafting for 80 experience and 8 gold.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_potion', 2, 0, 'Potion Practice: you crafted a potion. Return to a training mentor for 80 experience and 8 gold. You keep your potion.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_potion', 3, 1, 'Potion Practice complete. You received 80 experience and 8 gold. Speak to a mentor again to begin A Safe Journey.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_supplies', 1, 0, 'Field Supplies: bring one Mucor Mushroom and one full 100-unit Tallow bundle to a training mentor. Buy them from the quartermaster for 2 gold each and keep them in your bag. Your reward is a health potion, 80 experience and 6 gold.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_supplies', 2, 1, 'Field Supplies complete. You received a health potion, 80 experience and 6 gold. Use the crafting panel to combine a Mucor Mushroom and 100 Tallow into a health or vigor potion. Speak to a mentor again to begin Potion Practice.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_training', 1, 0, 'Training creatures defeated: {count}/{goal}. Equip a starter weapon from your bag and defeat Idol Spawn. Return to a training mentor after 3 kills.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_training', 2, 0, 'Training creatures defeated: 3/3. Leave combat and speak to a training mentor for 120 experience and 10 gold.', 'Pyrealium training lesson text', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('training_training', 3, 1, 'Training complete. You received 120 experience and 10 gold. Speak to a training mentor again for the Field Supplies lesson.', 'Pyrealium training lesson text', 'hand');
