INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_47000855', 1, 'Say', 0, 'Icefire. Begins with: Frostbound One , 37.9W 3.0S. Starting area: Winterhollows. Requirements: Level 40+ (plus special requirements below). Time allowed: 20 hours. Repeat interval: 6 days. Listed experience reward: 15,000,000. Listed rewards: Weapon of the Ancients upgraded to Weapon of the Sun''s Blaze. Information only; no task has been started.', 'Frostbound One', '', '', '', 'https://20oz.net/index.php/Icefire.html', 'npc');
