INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040a7', 1, 'Say', 0, 'Siege Stores. Begins with: Torgara (30.5S, 34.2E). Starting area: Center of Skyport , Knorr Wilds. Requirements: Level 30+. Time allowed: 10 hours. Repeat interval: 6 days. Listed experience reward: 25% (Cap: 12,518,366 @ L45). Listed rewards: 30,000 XP for each extra bread. Information only; no task has been started.', 'Torgara', '', '', '', 'https://20oz.net/index.php/Siege_Stores.html', 'npc');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040ea_1', 1, 'Say', 0, 'Journey to Fort Strathelar. After the Aerie assignments, Otonku needs a report carried to Legionary Brigadier Maekarn at Fort Strathelar. Begins with: Elite Legionary Otonku (38.7S, 45.4E). Starting area: The Aerie in Knorr Ramparts. Requirements: need all The Aerie Slays and Exterminate quests completed. Intended Level : 70. Time allowed: 6 days 23hours. Repeat interval: 6 days 23hours. Information only; no task has been started.', 'Elite Legionary Otonku', '', '', '', 'https://20oz.net/index.php/Journey_to_Fort_Strathelar.html', 'npc');
