INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_combat', 1, 'Say', 0, 'Equip a starter weapon, select an Idol Spawn, and use your attack or a trained starter attack skill. Stay in range and watch your health and vigor. Defeat three Idol Spawn for Training Grounds, leave combat, then use me to claim the reward.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_crafting', 1, 'Say', 0, 'The quartermaster sells Mucor Mushrooms and 100-unit Tallow bundles for 2 gold each. The crafting panel offers health and vigor potion recipes. Put one mushroom and a full Tallow bundle in your bag, choose the recipe, assign both ingredients and craft while out of combat. Field Supplies delivery uses its own pair of ingredients.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_gear', 1, 'Say', 0, 'Your starter weapons are in your bag and your starter clothing is already worn. Drag a weapon to its equipment slot, or use it from your bag. Drag it back into your bag to unequip. Keep your racial starter gear; the quartermaster also sells a development training weapon.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_healing', 1, 'Say', 0, 'Leave combat before using a health or vigor potion from your bag. Health potions restore health; vigor potions restore vigor. Use a nearby lifestone while alive and out of combat to bind a recall point. If defeated, use the resurrection control before continuing your lessons.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_help', 1, 'Say', 0, 'I can help with gear, combat, healing, supplies, crafting and travel. Ask @mentor followed by one of those topics. Use me normally to accept the next lesson or deliver a completed objective. Your journal keeps all four lessons across logins.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_quest', 1, 'Say', 0, 'Your journal (the Quest panel) shows each lesson''s step; use me to take the next lesson or claim a finished one. @quest lists them too.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_quests', 1, 'Say', 0, 'Your journal (the Quest panel) shows each lesson''s step; use me to take the next lesson or claim a finished one. @quest lists them too.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_supplies', 1, 'Say', 0, 'Your journal (the Quest panel) shows what Field Supplies asks for.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_ask_travel', 1, 'Say', 0, 'The nearby training portal links your start to the shared training area. The Human room and corridor have exits to the outdoor hub. Examine the hub portals to see their destinations: Human training room, Tumerok start or Lugian start. Leave combat and stand near a portal before using it.', 'Pectar, Training Master', '', '', '', 'the mentor''s @mentor topics (Pyrealium text: his DAT table 0x25001762 holds only his name)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_complete', 1, 'Say', 0, 'You have finished my lessons. The outdoor hub connects all three racial starts; its mentors and quartermasters remain available. Ask @mentor help for advice.', 'Pectar, Training Master', '', '', '', 'Pyrealium training lessons (policy)', 'hand');
