INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_lesson_offer', 2, 'Say', 0, 'Welcome to the Training Grounds. Equip a starter weapon from your bag and defeat three Idol Spawn, then return to me for 120 experience and 10 gold. Ask @mentor help while nearby for lessons on gear, combat, healing, crafting and travel.', 'Pectar, Training Master', '', '', '', 'Pyrealium training lessons (policy)', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('training_potion_busy', 1, 'Say', 0, 'Craft a health or vigor potion from a Mucor Mushroom and 100 Tallow in the crafting panel, then return to me. Bought potions do not count.', 'Pectar, Training Master', '', '', '', 'Pyrealium training lessons (policy)', 'hand');
