INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s1_ok', 2, 'Tell', 0, '0x250017ea', '0x668008ab', '', '', '', 'DAT string table 0x250017ea key 0x668008ab; user override: DAT tumerokshrethwardenquest.stt (250017ea) key 668008ab: Kiral on the letter, ''Hmm... this is disturbing. Lupe''s hunting must have angered the Ero-Bals ... While carrying this talisman, release three Ero-Bals''', 'vault');
