INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 2, 'Tell', 0, '0x250017ea', '0xee19ab23', '', '', '', 'DAT string table 0x250017ea key 0xee19ab23; user override: DAT tumerokshrethwardenquest.stt (250017ea) key ee19ab23: emote ''Kiral closes her eyes and mutters a few words as she turns the Tiny Wooden Talisman over and over in her hands.''', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 3, 'Tell', 0, '0x250017ea', '0xee19b323', '', '', '', 'DAT string table 0x250017ea key 0xee19b323; user override: DAT tumerokshrethwardenquest.stt (250017ea) key ee19b323: ''Ah, excellent. I sense much rage and hatred in this talisman. But if we calm the spirits thus...''', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 4, 'Tell', 0, '0x250017ea', '0xee19a323', '', '', '', 'DAT string table 0x250017ea key 0xee19a323; user override: DAT tumerokshrethwardenquest.stt (250017ea) key ee19a323: ''The talisman has been blessed with release. Tell Lupe to wear this around her neck ...''', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 5, 'GiveItem', 0, '0x47002338', '1', '', '', '', 'user override: DAT wsl_talismanwoodenblessed.entity (talismanwoodenblessed.stt 25007601 ''Blessed Wooden Talisman[E]''; questlupe.stt b17a221e calls it the Blessed Talisman of Rest); AC2 Vault quests/db id 103: the player receives Blessed Wooden Talisman', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 6, 'SetStage', 0, 'v103', '6', '', '', '', 'AC2 Vault quests/db id 103', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_start', 1, 'Tell', 0, '0x250074b1', '0x83889cdb', '', '', '', 'DAT string table 0x250074b1 key 0x83889cdb; user override: DAT lupe.stt (250074b1) key 83889cdb: ''I have been disturbed by terrible dreams of late ... Please take this letter to the scholar Kiral in Rakani.''', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_start', 2, 'GiveItem', 0, '0x4700234b', '1', '', '', '', 'user override: DAT wsl_lettertokiral.entity (lettertokiral.stt 2500760e ''Letter to Kiral''); keyed ''Lupe Letter'' because the step grammar splits an item name on '' to ''; AC2 Vault quests/db id 103: the player receives Lupe Letter', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_start', 3, 'SetStage', 0, 'v103', '1', '', '', '', 'AC2 Vault quests/db id 103', 'vault');
