INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_turn_in_ok', 1, 'TakeItem', 0, '0x47002338', '1', '', '', '', 'AC2 Vault quests/db id 103: hand 1 Blessed Wooden Talisman to Lupe', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_turn_in_ok', 2, 'Tell', 0, '0x250074b1', '0xde1e023b', '', '', '', 'DAT string table 0x250074b1 key 0xde1e023b; user override: DAT lupe.stt (250074b1) key de1e023b: ''This is supposed to cure my bad dreams? It doesn''t look like much of anything at all...''', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_turn_in_ok', 3, 'Tell', 0, '0x250074b1', '0xde1d023b', '', '', '', 'DAT string table 0x250074b1 key 0xde1d023b; user override: DAT lupe.stt (250074b1) key de1d023b: emote ''Lupe hangs the talisman about her neck. ... She smiles.''', 'vault');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_turn_in_ok', 4, 'Tell', 0, '0x250074b1', '0xde1c023b', '', '', '', 'DAT string table 0x250074b1 key 0xde1c023b; user override: DAT lupe.stt (250074b1) key de1c023b: ''Oh... I can feel the evil influences draining away! ... Let me reward you for your time and effort.''', 'vault');
